          if ($row.find('.deactivate a').length) {
            cy.wrap($row).find('.deactivate a').should('exist');
          } else if ($row.find('.activate a').length) {
            cy.wrap($row).find('.activate a').click();
            cy.get('@starterTemplatePluginRow').find('.deactivate a', { timeout: 15000 }).should('exist');
